"""The plane-parallel power spectrum terms generated by mathwap (pk/Pk_PP.py): NPP, GR1, GR2 and PNG to l = 6, which
pk.combined puts on CosmoWAP's classes.

Every l, with and without FoG, against projecting the class's own mu (NPP, GR - pk/Pk_0.py) or the numeric kernels
(PNG, keeping fNL^2), and down to k sigma ~ 1e-3, where erf closed forms lose their digits.
"""

import numpy as np
import pytest
from scipy.special import eval_legendre

from cosmo_wap import pk
from cosmo_wap.numeric_mu import pk as numeric_pk
from cosmo_wap.pk import Pk_PP

K = np.array([0.003, 0.02, 0.1, 0.25])
ZZ = 1.0
X, W = np.polynomial.legendre.leggauss(128)
NAMES = ["NPP", "GR1", "GR2", "Loc", "Eq", "Orth"]


def _project(P, l, sigma, k=K):
    """(2l+1)/2 int P L_l dmu of P on the nodes X, damped as the closed forms: exp(-(k mu sigma)^2/2)"""
    damp = 1 if sigma is None else np.exp(-((k[None, :] * X[:, None] * sigma) ** 2) / 2)
    return (2 * l + 1) / 2 * np.sum(W[:, None] * P * damp * eval_legendre(l, X)[:, None], axis=0)


def _real(cls, l):
    return getattr(getattr(cls, f"l{l}", None), "__name__", "empty_array_func") != "empty_array_func"


def test_multipoles_are_generated():
    """every multipole Pk_PP has, and its mu and l where the class had none (the PNG ones)"""
    for name in NAMES:
        cls, src = getattr(pk, name), getattr(Pk_PP, "_" + name)
        assert all(getattr(cls, f"l{l}") is getattr(src, f"l{l}") for l in range(7) if _real(src, l)), name
        png = name in ("Loc", "Eq", "Orth")
        assert (cls.mu is src.mu) == png and (cls.l is src.l) == png, name


@pytest.mark.parametrize("shape", ["Loc", "Eq", "Orth"])
def test_png_l_is_a_multipole(cosmo_funcs_png, shape):
    """l(l, ...) - numeric mu integration, as every other class's - is the l-th multipole"""
    cls = getattr(pk, shape)
    scale = np.abs(cls.l0(cosmo_funcs_png, K, ZZ, fNL=3.0)).max()
    for l in (0, 2, 4):  # l4 is zero without FoG
        want = getattr(cls, f"l{l}")(cosmo_funcs_png, K, ZZ, fNL=3.0)
        np.testing.assert_allclose(cls.l(l, cosmo_funcs_png, K, ZZ, fNL=3.0), want, rtol=1e-12, atol=1e-12 * scale)
    override = {f"fNL_{shape.lower()}": 3.0}
    np.testing.assert_allclose(cls.l(2, cosmo_funcs_png, K, ZZ, **override), cls.l(2, cosmo_funcs_png, K, ZZ, fNL=3.0))


@pytest.mark.parametrize("name", ["NPP", "GR1", "GR2"])
def test_against_mu(forecast_mt, name):
    """two tracers, so GR1 is not zero"""
    cf = forecast_mt.cosmo_funcs
    cls = getattr(pk, name)
    P = np.array([cls.mu(x, cf, K, ZZ) for x in X])
    for l in range(7):
        if not _real(cls, l):
            continue
        for sigma in (None, 4.0):
            got = getattr(cls, f"l{l}")(cf, K, ZZ, 0, sigma)
            np.testing.assert_allclose(
                got, _project(P, l, sigma), rtol=0, atol=1e-11 * np.abs(P).max(), err_msg=f"l{l}"
            )


def test_gr2_l4_is_not_a_stand_in(cosmo_funcs):
    """zero without FoG, but not with it - pk_func sees it too"""
    np.testing.assert_allclose(pk.GR2.l4(cosmo_funcs, K, ZZ), 0, atol=0)
    l4 = pk.pk_func("GR2", 4, cosmo_funcs, K, zz=ZZ, sigma=4.0)
    assert np.abs(l4).max() > 1e-3 * np.abs(pk.pk_func("GR2", 0, cosmo_funcs, K, zz=ZZ, sigma=4.0)).max()


def test_fog_at_small_k_sigma(forecast_mt):
    """pk_func's sigma = 2 (sqrt 2 x 2 in the multipoles' convention) at k down to 1e-3 - erf closed forms are off by
    ~5e8 for NPP.l4 there, and by ~1 for GR1.l3 (two tracers)"""
    cf, k = forecast_mt.cosmo_funcs, np.array([0.001, 0.003, 0.01, 0.03])
    for name, l in [("NPP", 2), ("NPP", 4), ("GR1", 3), ("GR2", 2)]:
        P = np.array([getattr(pk, name).mu(x, cf, k, ZZ) for x in X])
        want = _project(P, l, 2 * np.sqrt(2), k)
        np.testing.assert_allclose(
            pk.pk_func(name, l, cf, k, zz=ZZ, sigma=2.0), want, rtol=1e-9, err_msg=f"{name}.l{l}"
        )


@pytest.mark.parametrize("shape", ["Loc", "Eq", "Orth"])
def test_png(cosmo_funcs_png, shape):
    """every l against the numeric kernels' N + shape minus N - at fNL = 1 and 37, so the fNL^2 term counts"""
    cf, cls = cosmo_funcs_png, getattr(pk, shape)
    gauss = numeric_pk.get_mu(X, ["N"], ["N"], cf, K[:, None], ZZ).T
    for fNL in (1.0, 37.0):
        P = numeric_pk.get_mu(X, ["N", shape], ["N", shape], cf, K[:, None], ZZ, fNL=fNL).T - gauss
        for l in (0, 2, 4, 6):
            for sigma in (None, 4.0):
                got = getattr(cls, f"l{l}")(cf, K, ZZ, 0, sigma, fNL=fNL)
                np.testing.assert_allclose(got, _project(P, l, sigma), rtol=0, atol=1e-10 * np.abs(P).max())
    override = {f"fNL_{shape.lower()}": 5.0}
    np.testing.assert_allclose(cls.l4(cf, K, ZZ, 0, 4.0, **override), cls.l4(cf, K, ZZ, 0, 4.0, fNL=5.0))
